import CoreMedia

/// The picture the `av1` row writes (spec §11 CX-14): the SDR version or BT.709 (`sdr`), the
/// HLG master (`hlg`) or HDR10 (`pq`), read from the settings' `color` — which the core writes
/// only in an HLG project, so an SDR project is `.sdr`.
///
/// One value carries everything the three places that label the picture need, so they cannot
/// disagree: the luma weights `ExportI010.metal` converts with (CX-14 (3)), the CICP SVT-AV1
/// writes into the sequence header and the `colr` the `av01` entry carries (CX-14 (4)), and on
/// PQ alone HD-5's fixed HDR10 metadata, both as SVT's metadata OBUs and as the entry's
/// `mdcv`/`clli` (CX-14 (5)).
enum ExportAV1Picture: Equatable {
    case sdr, hlg, pq

    /// `hlg` and `pq` as named; anything else, absent included, is `.sdr`.
    init(color: String?) {
        switch color {
        case "hlg": self = .hlg
        case "pq": self = .pq
        default: self = .sdr
        }
    }

    /// The sequence header's `color_primaries`: BT.709, or BT.2020 for an HDR picture.
    var primaries: EbColorPrimaries {
        self == .sdr ? EB_CICP_CP_BT_709 : EB_CICP_CP_BT_2020
    }

    /// The sequence header's `transfer_characteristics`.
    var transfer: EbTransferCharacteristics {
        switch self {
        case .sdr: return EB_CICP_TC_BT_709
        case .hlg: return EB_CICP_TC_HLG
        case .pq: return EB_CICP_TC_SMPTE_2084
        }
    }

    /// The sequence header's `matrix_coefficients`: BT.709, or BT.2020 non-constant luminance.
    var matrix: EbMatrixCoefficients {
        self == .sdr ? EB_CICP_MC_BT_709 : EB_CICP_MC_BT_2020_NCL
    }

    /// The matrix's (Kr, Kb), the weights the kernel derives Y′, Cb′ and Cr′ from.
    var lumaWeights: (kr: Float, kb: Float) {
        self == .sdr ? (0.2126, 0.0722) : (0.2627, 0.0593)
    }

    /// The format description's colour extensions — the `colr` box, video range — and on PQ
    /// HD-5's mastering display and content light level (`OutputTransform`'s blobs, the `mdcv`
    /// and `clli` boxes).
    var formatExtensions: [String: Any] {
        var out: [String: Any] = [
            kCMFormatDescriptionExtension_ColorPrimaries as String: self == .sdr
                ? kCMFormatDescriptionColorPrimaries_ITU_R_709_2
                : kCMFormatDescriptionColorPrimaries_ITU_R_2020,
            kCMFormatDescriptionExtension_YCbCrMatrix as String: self == .sdr
                ? REDACTED
                : REDACTED,
            kCMFormatDescriptionExtension_FullRangeVideo as String: false,
        ]
        switch self {
        case .sdr:
            out[kCMFormatDescriptionExtension_TransferFunction as String] =
                REDACTED
        case .hlg:
            out[kCMFormatDescriptionExtension_TransferFunction as String] =
                REDACTED
        case .pq:
            out[kCMFormatDescriptionExtension_TransferFunction as String] =
                REDACTED
        }
        if carriesHDR10 {
            out[kCMFormatDescriptionExtension_MasteringDisplayColorVolume as String] =
                OutputTransform.masteringDisplay
            out[kCMFormatDescriptionExtension_ContentLightLevelInfo as String] =
                OutputTransform.contentLightLevel
        }
        return out
    }

    /// Whether HD-5's HDR10 metadata is written: on PQ alone.
    var carriesHDR10: Bool {
        self == .pq
    }

    /// `OutputTransform.masteringDisplay` in the form `svt_aom_parse_mastering_display` reads:
    /// P3's green, blue and red primaries and D65 as x, y, then the maximum and minimum
    /// luminance in cd/m².
    static let masteringDisplay =
        "G(0.265,0.690)B(0.150,0.060)R(0.680,0.320)WP(0.3127,0.3290)L(1000,0.005)"

    /// `OutputTransform.contentLightLevel` in the form `svt_aom_parse_content_light_level`
    /// reads: MaxCLL, MaxFALL.
    static let contentLightLevel = "1000,0"
}
import AVFoundation

/// `rc_webm_open`'s layout (spec §11 CX-15 (3)), the `Encodable` mirror of the core's
/// `WebmLayout`: what the `av1_webm` file is before its first packet. Built from the
/// settings (the size `ExportWriter.encodedSize` gives the encoder, the rate), the pump's
/// `av1C` record and sequence-header colour, its picture (HD-5's HDR10 blobs on PQ alone),
/// the Opus pre-skip when the composition has sound, and the chapters clamped and rebased
/// by `ExportChapter.partition` — the MP4 writer's own rule.
struct ExportWebMLayout: Encodable {
    struct Video: Encodable {
        let codecId = "V_AV1"
        let codecPrivateHex: String
        let width: Int
        let height: Int
        let fps: [Int]
        let colour: Colour
    }

    /// The sequence header's CICP, video range (Matroska's Range 1), 10 bits, and on PQ the
    /// two blobs `OutputTransform` writes everywhere else.
    struct Colour: Encodable {
        let matrix: Int
        let range = 1
        let transfer: Int
        let primaries: Int
        let bitsPerChannel = 10
        let mdcvHex: String?
        let clliHex: String?
    }

    struct Audio: Encodable {
        let codecId = "A_OPUS"
        let channels = 2
        let sampleRate = 48_000
        let preSkip: Int
    }

    struct Chapter: Encodable {
        let startNs: Int64
        let endNs: Int64
        let name: String
    }

    let durationNs: Int64
    let video: Video
    /// nil for a composition with no sound: the silent movie (CX-15 (2)).
    let audio: Audio?
    let chapters: [Chapter]

    init(
        settings: ExportSettings, range: CMTimeRange, config: ReelAV1.Config,
        picture: ExportAV1Picture, preSkip: Int?, chapters: [ExportChapter]
    ) {
        let frame = ExportWriter.encodedSize(settings)
        let hdr10 = picture.carriesHDR10
        durationNs = ExportWebMPacketSink.nanoseconds(range.duration)
        video = Video(
            codecPrivateHex: Self.hex(config.record), width: frame.width, height: frame.height,
            fps: [settings.fps.num, settings.fps.den],
            colour: Colour(
                matrix: config.color.matrix, transfer: config.color.transfer,
                primaries: config.color.primaries,
                mdcvHex: hdr10 ? Self.hex(OutputTransform.masteringDisplay) : nil,
                clliHex: hdr10 ? Self.hex(OutputTransform.contentLightLevel) : nil))
        audio = preSkip.map { Audio(preSkip: $0) }
        self.chapters = ExportChapter.partition(chapters, in: range).map {
            Chapter(
                startNs: ExportWebMPacketSink.nanoseconds($0.range.start),
                endNs: ExportWebMPacketSink.nanoseconds($0.range.end), name: $0.name)
        }
    }

    /// The layout as the core reads it: snake_case keys, an absent optional left out.
    func json() throws -> String {
        let encoder = JSONEncoder()
        encoder.keyEncodingStrategy = .convertToSnakeCase
        guard let text = String(data: try encoder.encode(self), encoding: .utf8) else {
            throw Exporter.ExportError.failed("The WebM layout could not be written.")
        }
        return text
    }

    private static func hex(_ data: Data) -> String {
        data.map { String(format: "%02x", $0) }.joined()
    }
}

