#[test]
fn every_layout_refusal_is_its_sentence() {
    let video = video_layout([30, 1], false);
    let mut cases: Vec<(Value, String)> = Vec::new();
    let with = |key: &str, value: Value| {
        let mut l = full_layout();
        l["video"][key] = value;
        l
    };
    cases.push((
        json!({"duration_ns": SECOND}),
        "the layout has no video and no audio track".into(),
    ));
    cases.push((
        with("codec_id", json!("V_VP9")),
        "video codec_id \"V_VP9\" is not V_AV1".into(),
    ));
    cases.push((
        with("codec_private_hex", json!("")),
        "the V_AV1 codec_private_hex is empty".into(),
    ));
    cases.push((
        with("codec_private_hex", json!("8z")),
        "codec_private_hex \"8z\" is not hex".into(),
    ));
    cases.push((
        with("width", json!(0)),
        "the video size 0 × 360 has a side of 0".into(),
    ));
    cases.push((
        with("fps", json!([30, 0])),
        "the video fps [30, 0] is not a rate".into(),
    ));
    pub fn finish(&self) -> Result<(), String> {
        let mut err: *mut c_char = ptr::null_mut();
        let ok = unsafe { rc_webm_finish(self.0, &mut err) };
        answer(ok, err)
    }
}

pub fn video_layout(fps: [u32; 2], pq: bool) -> Value {
    let mut colour = json!({"matrix": 9, "range": 1, "transfer": 16, "primaries": 9,
                            "bits_per_channel": 10});
    if pq {
        colour["mdcv_hex"] = json!(MDCV);
        colour["clli_hex"] = json!(CLLI);
    }
    json!({"codec_id": "V_AV1", "codec_private_hex": hex(&AV1C), "width": 640, "height": 360,
           "fps": fps, "colour": colour})
}

pub fn audio_layout() -> Value {
    json!({"codec_id": "A_OPUS", "channels": 2, "sample_rate": 48000, "pre_skip": PRE_SKIP})
}
